		&XMLWhenReportLoading;
		&XMLWhenReportClosing;





			&DeclareCommandFilter;



				&QueryString;

declare @queryWhereClause nvarchar(4000), @queryFormClause nvarchar(4000), @accountKey nvarchar(4000)
select @queryFormClause = ' left join dmkh b on a.ma_kh = b.ma_kh'
select @queryWhereClause = ' a.ngay_ct = ''' + @ngay + ''''
if @ma_dvcs <> '' select @queryWhereClause = @queryWhereClause + ' and ma_dvcs in (''' + replace(replace(replace(@ma_dvcs, ' ', ''), '''', ''''''), ',', ''',''') + ''')'
if isnull(@tk, '') <> '' begin
	select top 0 tk into #$tk from dmtk0
	exec dbo.FastBusiness$App$GetAccountKey 'a.tk', 'like', @tk, '#$tk', @@userID, @@admin, @accountKey output
	select @queryWhereClause = @queryWhereClause + ' and ' + @accountKey
end

select top 0 ma_td4 into #fcode4 from wrkgl
if @fcode4 <> '' begin
	insert into #fcode4 select ma_dtqt from dmdtqt4 where dbo.ff_ExactInlist(ma_dtqt, @fcode4) = 1
	set @queryWhereClause = @queryWhereClause + ' and exists(select 1 from dmtknh where ma_dvcs = a.ma_dvcs and tk = a.tk and ma_td4 = a.ma_td4 and ma_td4 in (select ma_td4 from #fcode4))'
end

&FilterInitialize;&FilterQuery;
exec FastBusiness$Report$GLDetail @@refresh, @@pageIndex, @@pageCount, @@lastPage, @@lastCount, @@firstItem, @@lastItem,
	@@textExternal, @queryFormClause, @queryWhereClause, @ngay, @ngay, @ma_dvcs, @@admin, @@userID, @@aggregation








			&JavascriptReportInit;
			/* <flatten type="Javascript"> */
function init$GridQuery$(g) {
	var a = g._queryFilterString.split(String.fromCharCode(253));
	g._alterTitle = [null, [['%c', a[2], true], ['%d', formatDateView(a[0]), true]]];
	var x = a[3];
	g._hiddenFields = [{Fields: 'ps_no_nt, ps_co_nt', Value: (x == '10')}];
}
/* </flatten> */



